	// The twelve tool pages, from the tool registry.
	$hub   = (string) mm_opt( 'tools_hub_slug' );
	$hub   = '' !== $hub ? trim( $hub, '/' ) : 'free-calculators';
	$order  = 0;
	$groups = array( 'profit' => __( 'Profit & comparison', 'minemirth' ), 'market' => __( 'Market & network', 'minemirth' ), 'planning' => __( 'Planning', 'minemirth' ) );
	foreach ( mm_tools() as $id => $t ) {
		$pages[ 'tool-' . $id ] = array(
			't'      => $t['title'],
			'p'      => $hub . '/' . $t['slug'],
			'parent' => 'tools',
			'tpl'    => 'tool',
			'tool'   => $id,
			'icon'   => $t['icon'],
			'g'      => $groups[ $t['group'] ] ?? '',
			'x'      => $t['desc'],
			'st'     => $t['title'] . ' ' . __( '(Free, Live Data)', 'minemirth' ),
			'sd'     => $t['desc'],
			'o'      => ++$order,
		);
	}
	$pages['tools']['p'] = $hub;
	return $pages;
}

/** Planned path of a builder page. */
function mm_builder_path( string $key ): string {
	$pages = mm_builder_pages();
	return isset( $pages[ $key ] ) ? $pages[ $key ]['p'] : '';
}
